/**
 * Password hashing for the app-manager admin panel.
 *
 * ADMIN_PASSWORD_HASH is a single self-describing string in the format
 *
 *   scrypt$N$r$p$<salt-hex>$<hash-hex>
 *
 * using Node's scrypt defaults (N=16384, r=8, p=1, 64-byte key). The
 * parameters are stored alongside the hash so they can be raised later
 * without breaking verification of previously stored hashes. The value is
 * generated by `npm run admin:hash` (scripts/admin-hash.mjs) and lives only
 * in /srv/callflow/.env — never in the repo.
 *
 * Verification is constant-time and fail-closed: any malformed or
 * non-parseable input simply returns false.
 */
import { randomBytes, scryptSync, timingSafeEqual } from "crypto";

const SALT_BYTES = 16;
const MIN_EXPECTED_HASH_BYTES = 32;

export interface AdminPasswordHashParts {
  N: number;
  r: number;
  p: number;
  salt: Buffer;
  expected: Buffer;
}

export function parseAdminPasswordHash(stored: string): AdminPasswordHashParts | null {
  const parts = stored.split("$");
  if (parts.length !== 6 || parts[0] !== "scrypt") return null;

  const N = Number(parts[1]);
  const r = Number(parts[2]);
  const p = Number(parts[3]);
  if (
    !Number.isInteger(N) ||
    !Number.isInteger(r) ||
    !Number.isInteger(p) ||
    N <= 0 ||
    r <= 0 ||
    p <= 0
  ) {
    return null;
  }

  const salt = Buffer.from(parts[4], "hex");
  const expected = Buffer.from(parts[5], "hex");
  // Buffer.from silently ignores invalid hex characters, so re-encode and
  // compare to prove both fields were clean hex of the expected length.
  if (salt.length !== SALT_BYTES || salt.toString("hex") !== parts[4]) return null;
  if (expected.length < MIN_EXPECTED_HASH_BYTES || expected.toString("hex") !== parts[5]) {
    return null;
  }
  return { N, r, p, salt, expected };
}

export function verifyAdminPassword(password: string, stored: string): boolean {
  if (!password || !stored) return false;
  const parts = parseAdminPasswordHash(stored);
  if (!parts) return false;
  try {
    const actual = scryptSync(password, parts.salt, parts.expected.length, {
      N: parts.N,
      r: parts.r,
      p: parts.p,
    });
    return timingSafeEqual(actual, parts.expected);
  } catch {
    // Unusable scrypt parameters (e.g. out-of-range cost) → fail closed.
    return false;
  }
}

/**
 * Builds a hash in the stored format. Used by tests to mint fixtures and to
 * pin the format contract with scripts/admin-hash.mjs (which independently
 * produces the same string; a test runs the real script and verifies its
 * output through this module).
 */
export function hashAdminPassword(
  password: string,
  salt: Buffer = randomBytes(SALT_BYTES)
): string {
  const N = 16384;
  const r = 8;
  const p = 1;
  const hash = scryptSync(password, salt, 64, { N, r, p });
  return `scrypt$${N}$${r}$${p}$${salt.toString("hex")}$${hash.toString("hex")}`;
}